// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address sender, uint256 collectAmount) internal {
        vm.assume(true);
        try c.Collect(collectAmount) {} catch { return; }
        bool reverted;
        try c.SetMinSum(1) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false);
    }

    function testFuzz_run(address sender, uint256 collectAmount) public {
        _run(sender, collectAmount);
    }

    receive() external payable { }
}
